  // No arithmetic/rounding changes; DAC latency increases from 3 to 4 clocks.
  generate
    for(sum_lane=0;sum_lane<12;sum_lane=sum_lane+1)begin: sum_pipeline
      always@(posedge clk)begin
        if(!rst_n)begin
          Add_sum_dly[sum_lane] <= 33'sd0;
        end
        else if(enb)begin
          case(sum_lane)
            0: Add_sum_dly[sum_lane] <= Add_add_temp;
            1: Add_sum_dly[sum_lane] <= Add_add_temp_1;
            2: Add_sum_dly[sum_lane] <= Add_add_temp_2;
            3: Add_sum_dly[sum_lane] <= Add_add_temp_3;
            4: Add_sum_dly[sum_lane] <= Add_add_temp_4;
            5: Add_sum_dly[sum_lane] <= Add_add_temp_5;
            6: Add_sum_dly[sum_lane] <= Add_add_temp_6;
            7: Add_sum_dly[sum_lane] <= Add_add_temp_7;
            8: Add_sum_dly[sum_lane] <= Add_add_temp_8;
            9: Add_sum_dly[sum_lane] <= Add_add_temp_9;
            10: Add_sum_dly[sum_lane] <= Add_add_temp_10;
            11: Add_sum_dly[sum_lane] <= Add_add_temp_11;
          endcase
        end
      end
    end
  endgenerate

  always @(posedge clk)
    begin : cd_0_process
      if (rst_n == 1'b0) begin
        cd_0_reg[0] <= 16'sb0000000000000000;
        cd_0_reg[1] <= 16'sb0000000000000000;
        cd_0_reg[2] <= 16'sb0000000000000000;
        cd_0_reg[3] <= 16'sb0000000000000000;
        cd_0_reg[4] <= 16'sb0000000000000000;
        cd_0_reg[5] <= 16'sb0000000000000000;
        cd_0_reg[6] <= 16'sb0000000000000000;
        cd_0_reg[7] <= 16'sb0000000000000000;
        cd_0_reg[8] <= 16'sb0000000000000000;
        cd_0_reg[9] <= 16'sb0000000000000000;
        cd_0_reg[10] <= 16'sb0000000000000000;
        cd_0_reg[11] <= 16'sb0000000000000000;
      end
      else begin
        if (enb) begin
          cd_0_reg[0] <= cd_0_reg_next[0];
          cd_0_reg[1] <= cd_0_reg_next[1];
          cd_0_reg[2] <= cd_0_reg_next[2];
          cd_0_reg[3] <= cd_0_reg_next[3];
          cd_0_reg[4] <= cd_0_reg_next[4];
          cd_0_reg[5] <= cd_0_reg_next[5];
          cd_0_reg[6] <= cd_0_reg_next[6];
          cd_0_reg[7] <= cd_0_reg_next[7];
          cd_0_reg[8] <= cd_0_reg_next[8];
          cd_0_reg[9] <= cd_0_reg_next[9];
          cd_0_reg[10] <= cd_0_reg_next[10];
          cd_0_reg[11] <= cd_0_reg_next[11];
        end
      end
    end

  assign cd_0_out1[0] = cd_0_reg[0];
  assign cd_0_out1[1] = cd_0_reg[1];
  assign cd_0_out1[2] = cd_0_reg[2];
  assign cd_0_out1[3] = cd_0_reg[3];
  assign cd_0_out1[4] = cd_0_reg[4];
  assign cd_0_out1[5] = cd_0_reg[5];
  assign cd_0_out1[6] = cd_0_reg[6];
  assign cd_0_out1[7] = cd_0_reg[7];
  assign cd_0_out1[8] = cd_0_reg[8];
  assign cd_0_out1[9] = cd_0_reg[9];
  assign cd_0_out1[10] = cd_0_reg[10];
  assign cd_0_out1[11] = cd_0_reg[11];
  assign cd_0_reg_next[0] = Add_out1[0];
  assign cd_0_reg_next[1] = Add_out1[1];
  assign cd_0_reg_next[2] = Add_out1[2];
  assign cd_0_reg_next[3] = Add_out1[3];
  assign cd_0_reg_next[4] = Add_out1[4];
  assign cd_0_reg_next[5] = Add_out1[5];
  assign cd_0_reg_next[6] = Add_out1[6];
  assign cd_0_reg_next[7] = Add_out1[7];
  assign cd_0_reg_next[8] = Add_out1[8];
  assign cd_0_reg_next[9] = Add_out1[9];
  assign cd_0_reg_next[10] = Add_out1[10];
  assign cd_0_reg_next[11] = Add_out1[11];


  assign Dout_0 = cd_0_out1[0];

  assign Dout_1 = cd_0_out1[1];

